const searchResults = $input.first().json.items || [];

return searchResults.map(item => ({
  json: {
    matched_video_id: item.id.videoId,
    matched_title: item.snippet.title,
    matched_description: item.snippet.description,
    matched_channel_id: item.snippet.channelId,
    matched_channel_name: item.snippet.channelTitle,
    matched_published_at: item.snippet.publishedAt,
    matched_thumbnail: item.snippet.thumbnails?.high?.url 
      || item.snippet.thumbnails?.medium?.url 
      || item.snippet.thumbnails?.default?.url,
    matched_url: `https://www.youtube.com/watch?v=${item.id.videoId}`
  }
}));

const url = $json["YouTube Video URL"];

if (!url) {
  throw new Error("No YouTube URL was provided.");
}

let videoId = null;

// Standard YouTube URL:
// https://www.youtube.com/watch?v=VIDEO_ID
const watchMatch = url.match(/[?&]v=([A-Za-z0-9_-]{11})/);

// Short URL:
// https://youtu.be/VIDEO_ID
const shortMatch = url.match(/youtu\.be\/([A-Za-z0-9_-]{11})/);

// Shorts:
// https://www.youtube.com/shorts/VIDEO_ID
const shortsMatch = url.match(/youtube\.com\/shorts\/([A-Za-z0-9_-]{11})/);

videoId =
  watchMatch?.[1] ||
  shortMatch?.[1] ||
  shortsMatch?.[1];

if (!videoId) {
  throw new Error("Invalid or unsupported YouTube URL.");
}

return {
  json: {
    youtube_url: url,
    video_id: videoId
  }
};

const channel = $json.items?.[0];

if (!channel) {
  throw new Error("No YouTube channel found for this Google account.");
}

return {
  json: {
    youtube_channel_id: channel.id,
    youtube_channel_name: channel.snippet?.title || "",
    youtube_handle: channel.snippet?.customUrl || "",
    authorized_at: new Date().toISOString()
  }
};

const candidate = $json;

// Get the original video response
const originalResponse = $("Get Original Video").item.json;

// YouTube API responses usually contain the video inside items[0]
const original = originalResponse.items?.[0] || originalResponse;

// Get authorized channel information
const authChannel = $("Prepare YouTube User").item.json;

// ------------------------------------
// ORIGINAL VIDEO INFORMATION
// ------------------------------------

const originalVideoId =
  original.video_id ||
  original.id ||
  "";

const originalChannelId =
  original.channel_id ||
  original.snippet?.channelId ||
  "";

const originalTitle =
  original.title ||
  original.snippet?.title ||
  "";

// ------------------------------------
// MATCHED VIDEO INFORMATION
// ------------------------------------

const matchedVideoId =
  candidate.matched_video_id || "";

const matchedChannelId =
  candidate.matched_channel_id || "";

const matchedTitle =
  candidate.matched_title || "";

// ------------------------------------
// COPYRIGHT SCORE
// ------------------------------------

let score = 0;
let reasons = [];

// 1. Same video ID
if (
  originalVideoId &&
  matchedVideoId &&
  matchedVideoId === originalVideoId
) {
  score += 100;
  reasons.push("Same video ID");
}

// 2. Same YouTube channel
if (
  matchedChannelId &&
  (
    matchedChannelId === originalChannelId ||
    matchedChannelId === authChannel.youtube_channel_id
  )
) {
  score += 40;
  reasons.push("Same YouTube channel");
}

// 3. Exact title match
if (
  originalTitle &&
  matchedTitle &&
  originalTitle.trim().toLowerCase() ===
  matchedTitle.trim().toLowerCase()
) {
  score += 30;
  reasons.push("Exact title match");
}

// ------------------------------------
// DETERMINE RISK LEVEL
// ------------------------------------

let risk_level;

if (score >= 100) {
  risk_level = "ORIGINAL";
} else if (score >= 50) {
  risk_level = "HIGH";
} else if (score >= 30) {
  risk_level = "MEDIUM";
} else {
  risk_level = "LOW";
}

// ------------------------------------
// DETERMINE IF THIS IS THE ORIGINAL
// ------------------------------------

const is_original =
  Boolean(originalVideoId) &&
  Boolean(matchedVideoId) &&
  matchedVideoId === originalVideoId;

// ------------------------------------
// RETURN RESULT
// ------------------------------------

return {
  json: {
    ...candidate,

    original_video_id: originalVideoId,
    original_title: originalTitle,

    copyright_score: score,
    risk_level,
    scan_reasons: reasons,

    is_original
  }
};

const api = $json.items?.[0];

if (!api) {
  throw new Error("No candidate video details were returned.");
}

// Candidate found by the search
const candidate = $("Normalize Candidates").item.json;

// Authenticated YouTube channel
const authChannel = $("Prepare YouTube User").item.json;

// Original video
const original = $("Get Original Video").item.json;

const snippet = api.snippet || {};
const contentDetails = api.contentDetails || {};
const stats = api.statistics || {};

return {
  json: {
    // Original video
    original_video_id: original.video_id || original.id || "",
    original_video_url: original.video_url || "",

    // Authenticated channel
    authorized_channel_id: authChannel.youtube_channel_id || "",
    authorized_channel_name: authChannel.youtube_channel_name || "",
    authorized_channel_handle: authChannel.youtube_handle || "",

    // Candidate
    matched_video_id: candidate.matched_video_id || api.id,
    matched_title: candidate.matched_title || snippet.title || "",
    matched_description: candidate.matched_description || snippet.description || "",
    matched_channel_id: candidate.matched_channel_id || snippet.channelId || "",
    matched_channel_name: candidate.matched_channel_name || "",
    matched_published_at: candidate.matched_published_at || snippet.publishedAt || "",
    matched_thumbnail: candidate.matched_thumbnail || "",
    matched_url: candidate.matched_url || `https://www.youtube.com/watch?v=${api.id}`,

    // Candidate details
    duration: contentDetails.duration || "",
    view_count: Number(stats.viewCount || 0),
    like_count: Number(stats.likeCount || 0),
    comment_count: Number(stats.commentCount || 0)
  }
};

const candidate = $json;

// Determine the match status
const score = candidate.copyright_score || 0;
const riskLevel = candidate.risk_level || "LOW";
const reasons = candidate.scan_reasons || [];

let status;

if (riskLevel === "HIGH") {
  status = "HIGH_COPYRIGHT_RISK";
} else if (riskLevel === "MEDIUM") {
  status = "POSSIBLE_COPYRIGHT_MATCH";
} else {
  status = "LOW_COPYRIGHT_RISK";
}

return {
  json: {
    status,

    is_original: false,

    submitted_video_id: candidate.original_video_id || "",
    submitted_video_url: candidate.original_video_url || "",

    authorized_channel_id: candidate.authorized_channel_id || "",
    authorized_channel_name: candidate.authorized_channel_name || "",
    authorized_channel_handle: candidate.authorized_channel_handle || "",

    matched_video_id: candidate.matched_video_id || "",
    matched_video_url: candidate.matched_url || "",

    matched_title: candidate.matched_title || "",
    matched_channel_id: candidate.matched_channel_id || "",
    matched_channel_name: candidate.matched_channel_name || "",
    matched_published_at: candidate.matched_published_at || "",

    duration: candidate.duration || "",
    view_count: candidate.view_count || 0,
    like_count: candidate.like_count || 0,
    comment_count: candidate.comment_count || 0,

    copyright_score: score,
    risk_level: riskLevel,
    scan_reasons: reasons,

    message:
      status === "HIGH_COPYRIGHT_RISK"
        ? "This video appears to strongly match another YouTube video."
        : status === "POSSIBLE_COPYRIGHT_MATCH"
        ? "This video may contain content that matches another YouTube video."
        : "This video has a low copyright match risk."
  }
};

const data = $json;

// ------------------------------------------------
// Helper: safely escape HTML
// ------------------------------------------------
function escapeHtml(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

// ------------------------------------------------
// Helper: create YouTube URL
// ------------------------------------------------
function getYouTubeUrl(videoUrl, videoId) {
  if (videoUrl) {
    return String(videoUrl);
  }

  if (videoId) {
    return `https://www.youtube.com/watch?v=${encodeURIComponent(videoId)}`;
  }

  return "";
}

// ------------------------------------------------
// Basic data
// ------------------------------------------------
const submittedVideoId = data.submitted_video_id || "";

const submittedVideoUrl = getYouTubeUrl(
  data.submitted_video_url,
  submittedVideoId
);

const submittedChannel =
  data.authorized_channel_name || "Unknown";

const status =
  data.overall_status ||
  data.status ||
  "REVIEW_REQUIRED";

const riskLevel =
  data.highest_risk_level ||
  data.risk_level ||
  "UNKNOWN";

const copyrightScore =
  data.highest_copyright_score ??
  data.copyright_score ??
  0;

const candidatesScanned =
  data.candidates_scanned ??
  0;

const possibleMatches =
  data.possible_matches ??
  (Array.isArray(data.matches) ? data.matches.length : 0);

const matches =
  Array.isArray(data.matches)
    ? data.matches
    : [];

// ------------------------------------------------
// Determine the first match title for subject
// ------------------------------------------------
const firstMatchTitle =
  matches.length > 0 && matches[0].title
    ? matches[0].title
    : "Potential Match";

// ------------------------------------------------
// Email subject
// ------------------------------------------------
const emailSubject =
  status === "REVIEW_REQUIRED"
    ? `⚠️ Copyright Review Required — ${firstMatchTitle}`
    : `YouTube Copyright Scan Result — ${status}`;

// ------------------------------------------------
// Build submitted video section
// ------------------------------------------------
let submittedVideoHtml = "";

if (submittedVideoUrl) {
  submittedVideoHtml = `
    <a
      href="${escapeHtml(submittedVideoUrl)}"
      target="_blank"
      style="
        display:inline-block;
        padding:10px 16px;
        background:#1a73e8;
        color:#ffffff;
        text-decoration:none;
        border-radius:5px;
        font-weight:bold;
      "
    >
      View Submitted Video
    </a>
  `;
} else {
  submittedVideoHtml = `
    <span style="color:#777;">
      No link available
    </span>
  `;
}

// ------------------------------------------------
// Build possible matches table
// ------------------------------------------------
let matchesHtml = "";

if (matches.length > 0) {

  const rows = matches.map((match, index) => {

    const matchVideoUrl = getYouTubeUrl(
      match.video_url,
      match.video_id
    );

    const number =
      match.number || index + 1;

    const title =
      match.title || "Unknown title";

    const channel =
      match.channel || "Unknown channel";

    const score =
      match.score ?? 0;

    const reason =
      match.reason || "Potential match";

    let reviewLink = "No link available";

    if (matchVideoUrl) {
      reviewLink = `
        <a
          href="${escapeHtml(matchVideoUrl)}"
          target="_blank"
          style="
            color:#1a73e8;
            text-decoration:none;
            font-weight:bold;
          "
        >
          View Video
        </a>
      `;
    }

    return `
      <tr>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
            text-align:center;
          "
        >
          ${escapeHtml(number)}
        </td>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
          "
        >
          <strong>
            ${escapeHtml(title)}
          </strong>
        </td>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
          "
        >
          ${escapeHtml(channel)}
        </td>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
            text-align:center;
          "
        >
          ${escapeHtml(score)}
        </td>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
          "
        >
          ${escapeHtml(reason)}
        </td>

        <td
          style="
            padding:10px;
            border:1px solid #ddd;
            text-align:center;
          "
        >
          ${reviewLink}
        </td>

      </tr>
    `;
  }).join("");

  matchesHtml = `
    <h3
      style="
        margin-top:30px;
        color:#333;
      "
    >
      Potential Copyright Matches
    </h3>

    <table
      style="
        border-collapse:collapse;
        width:100%;
        font-size:14px;
      "
    >

      <thead>

        <tr style="background:#f5f5f5;">

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
            "
          >
            #
          </th>

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
              text-align:left;
            "
          >
            Title
          </th>

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
              text-align:left;
            "
          >
            Channel
          </th>

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
            "
          >
            Score
          </th>

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
              text-align:left;
            "
          >
            Reason
          </th>

          <th
            style="
              padding:10px;
              border:1px solid #ddd;
            "
          >
            Review
          </th>

        </tr>

      </thead>

      <tbody>
        ${rows}
      </tbody>

    </table>
  `;

} else {

  matchesHtml = `
    <h3
      style="
        margin-top:30px;
        color:#333;
      "
    >
      Potential Copyright Matches
    </h3>

    <p style="color:#777;">
      No potential matches were found.
    </p>
  `;
}

// ------------------------------------------------
// Main HTML email
// ------------------------------------------------
const html = `

<div
  style="
    font-family:Arial,Helvetica,sans-serif;
    max-width:900px;
    margin:0 auto;
    color:#333;
    line-height:1.5;
  "
>

  <!-- Header -->

  <div
    style="
      background:#f3d3d3;
      border:1px solid #e6bebe;
      padding:20px;
      border-radius:8px;
      margin-bottom:20px;
    "
  >

    <h2
      style="
        margin:0;
        color:#b00020;
      "
    >
      ⚠️ Copyright Review Required
    </h2>

    <p style="margin:8px 0 0;">
      A potential copyright match was detected and requires manual review.
    </p>

  </div>


  <!-- Submitted Video -->

  <h3 style="margin-top:25px;">
    Submitted Video
  </h3>

  <table
    style="
      border-collapse:collapse;
      width:100%;
      margin-bottom:25px;
    "
  >

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
          width:35%;
        "
      >
        <strong>Video ID</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(submittedVideoId)}
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Channel</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(submittedChannel)}
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Video</strong>
      </td>

      <td style="padding:10px;">
        ${submittedVideoHtml}
      </td>

    </tr>

  </table>


  <!-- Scan Summary -->

  <h3>
    Scan Summary
  </h3>

  <table
    style="
      border-collapse:collapse;
      width:100%;
      margin-bottom:25px;
    "
  >

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
          width:50%;
        "
      >
        <strong>Status</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(status)}
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Risk Level</strong>
      </td>

      <td style="padding:10px;">
        <strong>
          ${escapeHtml(riskLevel)}
        </strong>
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Highest Copyright Score</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(copyrightScore)}
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Candidates Scanned</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(candidatesScanned)}
      </td>

    </tr>

    <tr>

      <td
        style="
          padding:10px;
          background:#f5f5f5;
        "
      >
        <strong>Possible Matches</strong>
      </td>

      <td style="padding:10px;">
        ${escapeHtml(possibleMatches)}
      </td>

    </tr>

  </table>


  <!-- Matches -->

  ${matchesHtml}


  <!-- Footer -->

  <p
    style="
      margin-top:30px;
      font-size:12px;
      color:#777;
    "
  >
    This notification was automatically generated by the
    YouTube Copyright Scan workflow.
  </p>

</div>

`;

// ------------------------------------------------
// Return data
// IMPORTANT:
// This node is "Run Once for Each Item",
// therefore return ONE item, not an array.
// ------------------------------------------------

return {
  json: {
    ...data,

    email_subject: emailSubject,

    email_html: html
  }
};

// Get all incoming candidate results
const 
candidates = $input.all().map(item => item.json);

if (candidates.length === 0) {
  return [];
}

// Basic information from the first candidate
const first = candidates[0];

const submittedVideoId =
  first.submitted_video_id || "";

// Find the candidate with the highest copyright score
const highestRiskCandidate = candidates.reduce((highest, current) => {
  const highestScore = Number(highest?.copyright_score || 0);
  const currentScore = Number(current?.copyright_score || 0);

  return currentScore > highestScore ? current : highest;
}, candidates[0]);

// Determine highest risk level
const riskLevels = candidates.map(c => c.risk_level || "LOW");

let highestRiskLevel = "LOW";

if (riskLevels.includes("HIGH")) {
  highestRiskLevel = "HIGH";
} else if (riskLevels.includes("MEDIUM")) {
  highestRiskLevel = "MEDIUM";
}

// Determine overall status
let status = "NO_COPYRIGHT_MATCH";

if (
  candidates.some(c =>
    c.status === "REVIEW_REQUIRED" ||
    c.status === "POSSIBLE_COPYRIGHT_MATCH"
  )
) {
  status = "REVIEW_REQUIRED";
} else if (
  candidates.some(c => c.status === "ORIGINAL")
) {
  status = "ORIGINAL";
}

// Collect all scan reasons
const reasons = [
  ...new Set(
    candidates.flatMap(c => {
      if (Array.isArray(c.scan_reasons)) {
        return c.scan_reasons;
      }

      if (c.scan_reasons) {
        return [c.scan_reasons];
      }

      return [];
    })
  )
];

// Create one summary item
return [
  {
    json: {
      scan_date: new Date().toISOString(),

      submitted_video_id: submittedVideoId,

      submitted_video_url:
        first.submitted_video_url || "",

      authorized_channel_name:
        first.authorized_channel_name || "",

      status,

      highest_risk_level: highestRiskLevel,

      highest_copyright_score:
        Number(highestRiskCandidate.copyright_score || 0),

      matched_video_id:
        highestRiskCandidate.matched_video_id || "",

      matched_video_url:
        highestRiskCandidate.matched_video_url || "",

      matched_title:
        highestRiskCandidate.matched_title || "",

      matched_channel_name:
        highestRiskCandidate.matched_channel_name || "",

      matched_published_at:
        highestRiskCandidate.matched_published_at || "",

      candidates_scanned:
        candidates.length,

      alert_sent:
        status === "REVIEW_REQUIRED" ? "YES" : "NO",

      scan_reasons:
        reasons.join(", "),

      message:
        status === "REVIEW_REQUIRED"
          ? "Potential copyright match detected. Manual review is required."
          : status === "ORIGINAL"
            ? "Original video detected."
            : "No significant copyright match detected."
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  return [];
}

const first = items[0].json;

// Find the highest-risk match
const highest = items.reduce((best, item) => {
  const score = Number(item.json.copyright_score || 0);
  const bestScore = Number(best.json.copyright_score || 0);

  return score > bestScore ? item : best;
}, items[0]).json;

// Build the list of matching videos
const matches = items.map((item, index) => {
  const data = item.json;

  return {
    number: index + 1,
    title: data.matched_title || "Unknown title",
    channel: data.matched_channel_name || "Unknown channel",
    score: Number(data.copyright_score || 0),
    reason: Array.isArray(data.scan_reasons)
      ? data.scan_reasons.join(", ")
      : data.scan_reasons || "Potential match",
    video_url: data.matched_video_url || ""
  };
});

return [
  {
    json: {
      submitted_video_id: first.submitted_video_id || "",
      submitted_video_url: first.submitted_video_url || "",
      authorized_channel_name: first.authorized_channel_name || "",

      overall_status: "REVIEW_REQUIRED",

      highest_risk_level: highest.risk_level || "LOW",
      highest_copyright_score: Number(highest.copyright_score || 0),

      candidates_scanned: items.length,
      possible_matches: matches.length,

      matches
    }
  }
];
